def maximum_safe_transactions(transactions):
    import heapq
    selected=[];balance=0
    for value in transactions:
        balance+=value;heapq.heappush(selected,value)
        while balance<0:
            removed=heapq.heappop(selected);balance-=removed
    return len(selected)

